PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS schools (id TEXT PRIMARY KEY, name TEXT NOT NULL, motto TEXT NOT NULL, address TEXT, telephone TEXT, email TEXT, website TEXT, logo_path TEXT, primary_colour TEXT NOT NULL, secondary_colour TEXT NOT NULL, accent_colour TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS academic_years (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), name TEXT NOT NULL, starts_on TEXT NOT NULL, ends_on TEXT NOT NULL, is_current INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, name));
CREATE TABLE IF NOT EXISTS terms (id TEXT PRIMARY KEY, academic_year_id TEXT NOT NULL REFERENCES academic_years(id), name TEXT NOT NULL, starts_on TEXT NOT NULL, ends_on TEXT NOT NULL, is_current INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(academic_year_id, name));
CREATE TABLE IF NOT EXISTS levels (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), name TEXT NOT NULL, display_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, name));
CREATE TABLE IF NOT EXISTS classes (id TEXT PRIMARY KEY, level_id TEXT NOT NULL REFERENCES levels(id), name TEXT NOT NULL, display_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(level_id, name));
CREATE TABLE IF NOT EXISTS streams (id TEXT PRIMARY KEY, class_id TEXT NOT NULL REFERENCES classes(id), name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(class_id, name));
CREATE TABLE IF NOT EXISTS departments (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, name));
CREATE TABLE IF NOT EXISTS subjects (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), department_id TEXT REFERENCES departments(id), code TEXT NOT NULL, name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, code));
CREATE TABLE IF NOT EXISTS houses (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), name TEXT NOT NULL, colour TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, name));
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), username TEXT NOT NULL, email TEXT, password_hash TEXT, status TEXT NOT NULL DEFAULT 'ACTIVE', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, username));
CREATE TABLE IF NOT EXISTS students (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), user_id TEXT UNIQUE REFERENCES users(id), admission_number TEXT NOT NULL, first_name TEXT NOT NULL, last_name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, admission_number));
CREATE TABLE IF NOT EXISTS staff (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), user_id TEXT UNIQUE REFERENCES users(id), staff_number TEXT NOT NULL, first_name TEXT NOT NULL, last_name TEXT NOT NULL, department_id TEXT REFERENCES departments(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, staff_number));
CREATE TABLE IF NOT EXISTS roles (id TEXT PRIMARY KEY, school_id TEXT REFERENCES schools(id), role_key TEXT NOT NULL, role_name TEXT NOT NULL, oversight_rank INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, role_key));
CREATE TABLE IF NOT EXISTS permissions (id TEXT PRIMARY KEY, permission_key TEXT NOT NULL UNIQUE, permission_name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_roles (user_id TEXT NOT NULL REFERENCES users(id), role_id TEXT NOT NULL REFERENCES roles(id), created_at TEXT NOT NULL, PRIMARY KEY(user_id, role_id));
CREATE TABLE IF NOT EXISTS role_permissions (role_id TEXT NOT NULL REFERENCES roles(id), permission_id TEXT NOT NULL REFERENCES permissions(id), created_at TEXT NOT NULL, PRIMARY KEY(role_id, permission_id));
CREATE TABLE IF NOT EXISTS sidebar_categories (id TEXT PRIMARY KEY, category_key TEXT NOT NULL UNIQUE, category_name TEXT NOT NULL, display_order INTEGER NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sidebar_modules (id TEXT PRIMARY KEY, module_key TEXT NOT NULL UNIQUE, module_name TEXT NOT NULL, category_id TEXT NOT NULL REFERENCES sidebar_categories(id), route TEXT NOT NULL, icon TEXT NOT NULL, display_order INTEGER NOT NULL DEFAULT 0, required_permission TEXT REFERENCES permissions(permission_key), enabled INTEGER NOT NULL DEFAULT 1, parent_module_id TEXT REFERENCES sidebar_modules(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS system_settings (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES schools(id), setting_key TEXT NOT NULL, setting_value TEXT, value_type TEXT NOT NULL DEFAULT 'string', is_sensitive INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, setting_key));
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, school_id TEXT REFERENCES schools(id), user_id TEXT REFERENCES users(id), role_id TEXT REFERENCES roles(id), action TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT, previous_value TEXT, new_value TEXT, ip_address TEXT, session_id TEXT, device_metadata TEXT, occurred_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_terms_year ON terms(academic_year_id);
CREATE INDEX IF NOT EXISTS idx_classes_level ON classes(level_id);
CREATE INDEX IF NOT EXISTS idx_students_school ON students(school_id);
CREATE INDEX IF NOT EXISTS idx_staff_school ON staff(school_id);
CREATE INDEX IF NOT EXISTS idx_modules_category_order ON sidebar_modules(category_id, display_order);
CREATE INDEX IF NOT EXISTS idx_audit_entity ON audit_logs(entity, entity_id);
CREATE INDEX IF NOT EXISTS idx_audit_occurred_at ON audit_logs(occurred_at);
